import AppKit

/// Decides whether a pasteboard change may be recorded. Pure, so it is unit-tested directly.
enum PrivacyFilter {
    enum Verdict: Equatable { case capture, paused, excludedApp, concealed }

    static let markerTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",          // 1Password 7
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    static let defaultExcludedApps: [String] = [
        "com.1password.1password", "com.agilebits.onepassword7", "com.agilebits.onepassword-osx",
        "com.bitwarden.desktop", "org.keepassxc.keepassxc", "com.apple.keychainaccess",
        "com.apple.Passwords", "com.lastpass.LastPass", "com.dashlane.dashlanephonefinal",
        "in.sinew.Enpass-Desktop",
    ]

    /// Display names for the default list, so apps that aren't installed don't show as raw bundle IDs.
    static let knownNames: [String: String] = [
        "com.1password.1password": "1Password", "com.agilebits.onepassword7": "1Password 7",
        "com.agilebits.onepassword-osx": "1Password 6", "com.bitwarden.desktop": "Bitwarden",
        "org.keepassxc.keepassxc": "KeePassXC", "com.apple.keychainaccess": "Keychain Access",
        "com.apple.Passwords": "Passwords", "com.lastpass.LastPass": "LastPass",
        "com.dashlane.dashlanephonefinal": "Dashlane", "in.sinew.Enpass-Desktop": "Enpass",
    ]

    static func verdict(types: [String], sourceBundleID: String?, paused: Bool,
                        excludedApps: Set<String>) -> Verdict {
        if paused { return .paused }
        if !markerTypes.isDisjoint(with: types) { return .concealed }
        if let id = sourceBundleID, excludedApps.contains(id) { return .excludedApp }
        return .capture
    }
}
